261	const CLOUD_VERT = /* glsl */ `
262	attribute vec4 aLobe;     // centre (group-local), radius
263	attribute vec2 aTone;     // brightness jitter, iridescence seed
264	uniform vec2 uGuard;
265	uniform vec3 uProjPos;
266	uniform float uClip;
267	uniform float uMagOn;     // 1 = level stretch: a lobe rises only where the moving view magnifies the water past what the approved view showed
268	uniform float uCScale;
269	varying vec3 vPv;
270	varying vec3 vCv;
271	varying float vR;
272	varying vec2 vTone;
273	void main() {
274	  vec4 wc = modelMatrix * vec4(aLobe.xyz, 1.0);
275	  float pres = 1.0;
276	  if (uMagOn > 0.5) {
277	    // the same stretch guard as the projected water (1 in the approved view → no cloud there: the painted foam shows)
278	    vec3 n = normalize(mat3(modelMatrix) * vec3(0.0, 1.0, 0.0));
279	    float cp = abs(dot(n, normalize(uProjPos - wc.xyz))), cc = abs(dot(n, normalize(cameraPosition - wc.xyz)));
280	    float mag = (cc / max(cp, 1e-3)) * (distance(uProjPos, wc.xyz) / max(distance(cameraPosition, wc.xyz), 1e-3));
281	    pres = smoothstep(uGuard.x, uGuard.y, mag);
282	    if (uClip > 0.0 && -aLobe.z > uClip) pres = 0.0;
283	  }
284	  float r = aLobe.w * uCScale * pres;
285	  vec4 cv = viewMatrix * wc;
286	  vCv = cv.xyz; vR = r; vTone = aTone;
287	  vec3 pv = cv.xyz + vec3(position.xy * r * 1.4, 0.0);
288	  vPv = pv;
289	  gl_Position = r > 1e-4 ? projectionMatrix * vec4(pv, 1.0) : vec4(2.0, 2.0, 2.0, 1.0);
290	}`;
291	const CLOUD_FRAG = /* glsl */ `
292	uniform mat4 projectionMatrix;
293	uniform vec4 uPjPost;
294	uniform vec2 uPjRes;
295	varying vec3 vPv;
296	varying vec3 vCv;
297	varying float vR;
298	varying vec2 vTone;
299	${PROJ05_INVERSE}
300	void main() {
301	  vec3 rd = normalize(vPv);
302	  float b = dot(rd, vCv);
303	  float c = dot(vCv, vCv) - vR * vR;
304	  float h = b * b - c;
305	  if (h < 0.0 || c < 0.0) discard;
306	  float t = b - sqrt(h);
307	  vec3 hit = rd * t;
308	  vec3 n = (hit - vCv) / vR;                         // view-space sphere normal
309	  vec4 clip = projectionMatrix * vec4(hit, 1.0);
310	  gl_FragDepthEXT = 0.5 * clip.z / clip.w + 0.5;
311	  vec3 nw = normalize((vec4(n, 0.0) * viewMatrix).xyz); // world normal (view rotation transposed)
312	  float nv = max(dot(n, -rd), 0.0);
313	  // painted foam tones (display values sampled from the approved picture): crevice, lavender-blue shadow, lilac mid, light, white.
314	  // White only on the lobe tops facing up / the viewer; the sides and undersides lavender-blue, the lobe outlines a little darker
