    // the same stretch guard as the projected water (1 in the approved view → no cloud there: the painted foam shows); as the view
    // magnifies the water the foam heaps up out of the water (the lobe rises from below the surface, a little smaller), it does not
    // inflate from a point
    vec4 w0 = modelMatrix * vec4(lc, 1.0);
    vec3 n = normalize(mat3(modelMatrix) * vec3(0.0, 1.0, 0.0));
