/**
 * r22 m07cloud: one painted cumulus mound beyond the band edge on one side (side = ±1), centred at along a; place(lat, along, up)
 * → group-local. Built like the painted foam: 2–4 big domes sunk into the water, softer lobes heaped on top of them, and many
 * small bumps half out of every big lobe (the lumpy cauliflower outline), a few loose bubbles at the river edge. Mound size and
 * spacing vary (no row of equal balls).
 */
type Place = (lat: number, a: number, up: number) => THREE.Vector3;
const edge = 2.95;
const pushL = (out: number[], tone: number[], place: Place, side: number, wallLat: number, lat: number, along: number, up: number, r: number, lvl: number) => {
  lat = Math.max(lat, edge - r * 0.35);
  if (lat + r * 0.25 > wallLat) lat = wallLat - r * 0.25;
  const p = place(side * lat, along, up);
  out.push(p.x, p.y, p.z, r); tone.push(rnd(), rnd(), lvl);
};
const mound = (out: number[], tone: number[], place: Place, side: number, a: number, wallLat: number, S: number) => {
  const room = Math.max(0.5, wallLat - edge);
  const lC = edge + Math.min(room * 0.55, 0.35 * S + 0.2 + 0.25 * rnd());
  const len = (0.8 + 0.6 * rnd()) * S;
  const big: [number, number, number, number][] = []; // lat, along, up, r
  const nB = 2 + Math.floor(rnd() * 3);
  for (let i = 0; i < nB; i++) {
    const r = (0.26 + 0.14 * rnd()) * S;
    const l = lC + (rnd() - 0.4) * 0.55 * S, da = (nB > 1 ? i / (nB - 1) - 0.5 : 0) * len + (rnd() - 0.5) * 0.2 * S;
    const up = -r * (0.2 + 0.3 * rnd());
    big.push([l, a + da, up, r]); pushL(out, tone, place, side, wallLat, l, a + da, up, r, 0.15);
  }
  // softer lobes heaped on top
  for (const [l, al, up, r] of big.slice()) {
    if (rnd() < 0.3) continue;
    const ru = r * (0.55 + 0.2 * rnd());
    const th = rnd() * Math.PI * 2, el = 0.55 + 0.35 * rnd();
    const dl = Math.cos(th) * Math.sqrt(1 - el * el), da = Math.sin(th) * Math.sqrt(1 - el * el);
    const c: [number, number, number, number] = [l + dl * r * 0.6, al + da * r * 0.6, up + el * r * 0.62, ru];
    big.push(c); pushL(out, tone, place, side, wallLat, c[0], c[1], c[2], ru, 0.6);
  }
  // small bumps half out of every big lobe (upper hemisphere and the sides; the side facing the river gets most of them)
  for (const [l, al, up, r] of big) {
    const nS = 2 + Math.floor(rnd() * 3);
    for (let k = 0; k < nS; k++) {
      const rs = r * (0.2 + 0.2 * rnd());
      const th = rnd() * Math.PI * 2, el = -0.1 + 0.95 * rnd();
      let dl = Math.cos(th) * Math.sqrt(1 - el * el); const da = Math.sin(th) * Math.sqrt(1 - el * el);
      if (dl > 0 && rnd() < 0.6) dl = -dl; // toward the river
      const cu = up + el * (r * 0.92);
      if (cu + rs < 0.02) continue;      // under the water: never seen
      pushL(out, tone, place, side, wallLat, l + dl * r * 0.92, al + da * r * 0.92, cu, rs, 0.4 + 0.6 * Math.max(el, 0));
    }
  }
  // loose bubbles at the river edge
  const nb = rnd() < 0.6 ? 1 + Math.floor(rnd() * 3) : 0;
  for (let k = 0; k < nb; k++) { const r = 0.035 + 0.05 * rnd(); pushL(out, tone, place, side, wallLat, edge - 0.05 + 0.2 * rnd(), a + (rnd() - 0.5) * len, r * 0.2, r, 0.7); }
};
/** the bank's lumpy foam line right beyond the magenta band (continuous, low, small lobes: the painted foam lines the river) */
const skirt = (out: number[], tone: number[], place: Place, side: number, a: number, wallLat: number) => {
  const r = 0.11 + 0.11 * rnd();
  pushL(out, tone, place, side, wallLat, edge + r * 0.45 + 0.08 * rnd(), a, -r * (0.15 + 0.3 * rnd()), r, 0.35);
  if (rnd() < 0.5) { const r2 = r * (0.45 + 0.25 * rnd()); pushL(out, tone, place, side, wallLat, edge + r * 0.7, a + (rnd() - 0.5) * 0.2, r * 0.45, r2, 0.75); }
};
/** a whole bank on one side from along a0 to a1: irregular mounds (size 0.75–1.5, now and then a big one against the wall, now
 *  and then a gap) and the continuous skirt */
const bank = (out: number[], tone: number[], place: (s: number) => Place, wall: (a: number) => number, side: number, a0: number, a1: number) => {
  for (let a = a0 + rnd(); a < a1; ) {
    const S = rnd() < 0.18 ? 1.35 + 0.35 * rnd() : 0.75 + 0.5 * rnd();
    if (rnd() > 0.12) mound(out, tone, place(a), side, a, wall(a), S);
    a += (0.75 + 0.7 * rnd()) * S + 0.25;
  }
  for (let a = a0; a < a1; a += 0.3 + 0.18 * rnd()) skirt(out, tone, place(a), side, a, wall(a));
};

