/** one cumulus cluster at lateral e (outward from the band edge, sign = side), along a; place(lat, along, up) → group-local */
const cluster = (out: number[], tone: number[], place: (lat: number, a: number, up: number) => THREE.Vector3, side: number, a: number, wallLat: number) => {
  const push = (lat: number, da: number, up: number, r: number) => {
    if (Math.abs(lat) + r * 0.3 > wallLat) lat = side * (wallLat - r * 0.3);
    const p = place(lat, a + da, up);
    out.push(p.x, p.y, p.z, r); tone.push(rnd(), rnd());
  };
  const edge = 2.95;
  // the mound: 3–4 big lobes overlapping heavily (domes rising out of the water), 1–2 lobes on top
  const rM = 0.36 + 0.22 * rnd(), lM = side * (edge + rM * 0.55 + 0.3 * rnd());
  const nB = 3 + (rnd() < 0.5 ? 1 : 0);
  for (let i = 0; i < nB; i++) {
    const r = rM * (0.7 + 0.35 * rnd());
    push(lM + side * (rnd() * 0.5 + (i % 2) * 0.35), (i - (nB - 1) / 2) * rM * 0.62 + (rnd() - 0.5) * 0.15, r * (0.02 + 0.12 * rnd()), r);
  }
  const nT = rnd() < 0.6 ? 2 : 1;
  for (let i = 0; i < nT; i++) { const r = rM * (0.5 + 0.2 * rnd()); push(lM + side * (0.15 + 0.3 * rnd()), (rnd() - 0.5) * rM, rM * (0.45 + 0.15 * rnd()), r); }
  // a few loose bubbles near the band edge
  if (rnd() < 0.55) { const r = 0.05 + 0.07 * rnd(); push(side * (edge + 0.05 + 0.25 * rnd()), (rnd() - 0.5) * 0.8, r * 0.3, r); }
  // a bigger mound lobe against the wall
  if (rnd() < 0.75) { const r = 0.38 + 0.3 * rnd(); push(side * (wallLat - 0.2), (rnd() - 0.5) * 0.6, r * 0.15, r); }
};

